-- Air Cargo Flights benchmark -- CRYPTIC schema (generated by scripts/build_variants.py from schema/schema.sql; do not edit)
PRAGMA foreign_keys = ON;

CREATE TABLE ts4p (
    c01 TEXT PRIMARY KEY,
    c02 TEXT NOT NULL
);

CREATE TABLE ts53 (
    c01 INTEGER PRIMARY KEY,
    c02 TEXT NOT NULL UNIQUE CHECK (length(c02) = 3),
    c03 TEXT NOT NULL UNIQUE CHECK (length(c03) = 4),
    c04 TEXT NOT NULL,
    c05 TEXT NOT NULL,
    c06 TEXT NOT NULL,
    c07 TEXT NOT NULL CHECK (c07 IN ('north_america', 'europe', 'middle_east', 'asia_pacific')),
    c08 TEXT NOT NULL,
    c09 REAL NOT NULL CHECK (c09  BETWEEN  -90 AND  90),
    c10 REAL NOT NULL CHECK (c10 BETWEEN -180 AND 180),
    c11 INTEGER NOT NULL,
    c12 INTEGER NOT NULL CHECK (c12 >= 1),
    c13 INTEGER NOT NULL CHECK (c13 > 0),
    c14 INTEGER NOT NULL DEFAULT 0 CHECK (c14 IN (0, 1)),
    c15 INTEGER NOT NULL CHECK (c15 > 0),
    c16 INTEGER NOT NULL CHECK (c16 IN (0, 1)),
    c17 INTEGER NOT NULL CHECK (c17 IN (0, 1))
);

CREATE TABLE twxv (
    c01 INTEGER PRIMARY KEY,
    c02 TEXT NOT NULL UNIQUE CHECK (length(c02) = 2),
    c03 TEXT NOT NULL UNIQUE CHECK (length(c03) = 3),
    c04 TEXT NOT NULL UNIQUE,
    c05 TEXT NOT NULL UNIQUE,
    c06 TEXT NOT NULL,
    c07 TEXT NOT NULL,
    c08 INTEGER NOT NULL CHECK (c08 BETWEEN 1900 AND 2025),
    c09 INTEGER NOT NULL REFERENCES ts53(c01),
    c10 TEXT CHECK (c10 IS NULL OR c10 IN ('CargoLink', 'SkyFreight Alliance')),
    c11 INTEGER NOT NULL CHECK (c11 IN (0, 1)),
    c12 TEXT NOT NULL UNIQUE,
    c13 TEXT NOT NULL,
    c14 TEXT NOT NULL
);

CREATE TABLE tumf (
    c01 INTEGER PRIMARY KEY,
    c02 TEXT NOT NULL UNIQUE,
    c03 TEXT NOT NULL UNIQUE,
    c04 TEXT NOT NULL,
    c05 INTEGER NOT NULL CHECK (c05 IN (2, 4)),
    c06 TEXT NOT NULL,
    c07 INTEGER NOT NULL CHECK (c07 > 0),
    c08 REAL    NOT NULL CHECK (c08 > 0),
    c09 INTEGER NOT NULL CHECK (c09 > 0),
    c10 INTEGER NOT NULL CHECK (c10 > 0),
    c11 INTEGER NOT NULL CHECK (c11 > 0),
    c12 INTEGER NOT NULL CHECK (c12 > 0),
    c13 INTEGER NOT NULL CHECK (c13 > 0),
    c14 INTEGER NOT NULL CHECK (c14 > 0),
    c15 INTEGER NOT NULL CHECK (c15 > 0),
    c16 REAL    NOT NULL CHECK (c16 > 0),
    CHECK (c12 + c07 <= c11)
);

CREATE TABLE tu5q (
    c01 INTEGER PRIMARY KEY,
    c02 TEXT NOT NULL UNIQUE,
    c03 TEXT NOT NULL UNIQUE,
    c04 INTEGER NOT NULL REFERENCES tumf(c01),
    c05 INTEGER NOT NULL REFERENCES twxv(c01),
    c06 INTEGER NOT NULL REFERENCES ts53(c01),
    c07 TEXT NOT NULL,
    c08 INTEGER NOT NULL CHECK (c08 BETWEEN 1990 AND 2025),
    c09 TEXT NOT NULL,
    c10 TEXT NOT NULL CHECK (c10 IN ('owned', 'leased')),
    c11 TEXT,
    c12 TEXT,
    c13 INTEGER NOT NULL CHECK (c13 >= 0),
    c14 INTEGER NOT NULL CHECK (c14 >= 0),
    c15 TEXT,
    c16 TEXT NOT NULL CHECK (c16 IN ('active', 'maintenance', 'retired')),
    CHECK ((c10 = 'leased') = (c11 IS NOT NULL AND c12 IS NOT NULL)),
    CHECK (CAST(substr(c09, 1, 4) AS INTEGER) >= c08)
);

CREATE TABLE th77 (
    c01 INTEGER PRIMARY KEY,
    c02 TEXT NOT NULL UNIQUE,
    c03 TEXT NOT NULL,
    c04 TEXT NOT NULL CHECK (c04 IN ('shipper', 'freight_forwarder', 'retailer', 'manufacturer')),
    c05 TEXT NOT NULL,
    c06 TEXT NOT NULL,
    c07 TEXT NOT NULL,
    c08 TEXT NOT NULL,
    c09 TEXT NOT NULL,
    c10 TEXT NOT NULL,
    c11 TEXT NOT NULL,
    c12 TEXT,
    c13 TEXT NOT NULL CHECK (c13 IN ('north_america', 'south_america', 'europe', 'middle_east', 'asia_pacific')),
    c14 REAL NOT NULL CHECK (c14 > 0),
    c15 INTEGER NOT NULL CHECK (c15 IN (15, 30, 45, 60)),
    c16 INTEGER NOT NULL CHECK (c16 IN (0, 1)),
    c17 TEXT NOT NULL CHECK (c17 IN ('bronze', 'silver', 'gold', 'platinum')),
    c18 TEXT NOT NULL,
    UNIQUE (c03, c05)
);

CREATE TABLE trhn (
    c01 INTEGER PRIMARY KEY,
    c02 TEXT NOT NULL UNIQUE,
    c03 INTEGER NOT NULL REFERENCES ts53(c01),
    c04 TEXT NOT NULL,
    c05 TEXT NOT NULL CHECK (c05 IN ('general', 'cold_chain', 'dangerous_goods', 'express')),
    c06 INTEGER NOT NULL CHECK (c06 > 0),
    c07 INTEGER NOT NULL CHECK (c07 > 0),
    c08 INTEGER NOT NULL CHECK (c08 >= 0),
    c09 REAL,
    c10 INTEGER NOT NULL CHECK (c10 > 0),
    c11 INTEGER NOT NULL CHECK (c11 IN (0, 1)),
    c12 INTEGER NOT NULL CHECK (c12 IN (0, 1)),
    c13 TEXT NOT NULL CHECK (c13 IN ('standard', 'high')),
    c14 INTEGER NOT NULL CHECK (c14 IN (0, 1)),
    c15 INTEGER NOT NULL CHECK (c15 BETWEEN 1950 AND 2025),
    c16 REAL NOT NULL CHECK (c16 > 0),
    CHECK ((c08 = 0) = (c09 IS NULL)),
    CHECK (c05 <> 'cold_chain' OR c08 > 0),
    CHECK (c05 <> 'dangerous_goods' OR c11 = 1)
);

CREATE TABLE t6sc (
    c01 INTEGER PRIMARY KEY,
    c02 TEXT NOT NULL UNIQUE,
    c03 TEXT NOT NULL,
    c04 TEXT NOT NULL,
    c05 TEXT NOT NULL UNIQUE,
    c06 INTEGER NOT NULL REFERENCES twxv(c01),
    c07 INTEGER NOT NULL REFERENCES ts53(c01),
    c08 TEXT NOT NULL CHECK (c08 IN ('captain', 'first_officer', 'loadmaster')),
    c09 INTEGER REFERENCES tumf(c01),
    c10 TEXT UNIQUE,
    c11 TEXT,
    c12 TEXT,
    c13 TEXT NOT NULL,
    c14 INTEGER NOT NULL CHECK (c14 >= 1),
    c15 INTEGER NOT NULL CHECK (c15 >= 0),
    c16 INTEGER NOT NULL CHECK (c16 IN (0, 1)),
    UNIQUE (c06, c14),
    CHECK ((c08 = 'loadmaster') = (c09 IS NULL)),
    CHECK ((c08 = 'loadmaster') = (c10 IS NULL AND c11 IS NULL AND c12 IS NULL))
);

CREATE TABLE tx7n (
    c01 INTEGER PRIMARY KEY,
    c02 TEXT NOT NULL,
    c03 TEXT NOT NULL CHECK (c03 IN ('scheduled', 'charter')),
    c04 INTEGER NOT NULL REFERENCES tu5q(c01),
    c05 INTEGER NOT NULL REFERENCES ts53(c01),
    c06 INTEGER NOT NULL REFERENCES ts53(c01),
    c07 TEXT NOT NULL,
    c08 TEXT NOT NULL,
    c09 TEXT,
    c10 TEXT,
    c11 TEXT NOT NULL,
    c12 TEXT NOT NULL,
    c13 INTEGER NOT NULL CHECK (c13 > 0),
    c14 INTEGER NOT NULL CHECK (c14 BETWEEN 20000 AND 43000),
    c15 INTEGER,
    c16 TEXT CHECK (c16 IS NULL OR c16 IN
                                   ('clear', 'cloudy', 'rain', 'snow', 'fog', 'thunderstorm')),
    c17 TEXT,
    c18 TEXT CHECK (c18 IS NULL OR c18 IN
                                   ('weather', 'technical', 'crew', 'commercial', 'atc')),
    c19 TEXT NOT NULL CHECK (c19 IN ('scheduled', 'completed', 'cancelled')),
    UNIQUE (c02, c07),
    CHECK (c05 <> c06),
    CHECK (c08 > c07),
    CHECK (
        (c19 = 'completed' AND c09 IS NOT NULL AND c10 IS NOT NULL
                              AND c10 > c09)
     OR (c19 <> 'completed' AND c09 IS NULL AND c10 IS NULL)
    ),
    CHECK ((c19 = 'completed') = (c15 IS NOT NULL)),
    CHECK ((c19 = 'cancelled') = (c18 IS NOT NULL)),
    CHECK ((c19 = 'scheduled') = (c16 IS NULL)),
    CHECK (c17 IS NULL OR c19 = 'completed')
);

CREATE TABLE tpsn (
    c01 INTEGER PRIMARY KEY,
    c02 INTEGER NOT NULL REFERENCES tx7n(c01),
