    c04 TEXT NOT NULL CHECK (c04 IN ('captain', 'first_officer', 'relief_pilot', 'loadmaster')),
    c05 INTEGER NOT NULL CHECK (c05 IN (0, 1)),
    c06 TEXT NOT NULL,
    c07 TEXT NOT NULL,
    c08 INTEGER,
