    c12 TEXT NOT NULL CHECK (c12 IN ('rostered', 'completed')),
    UNIQUE (c02, c03),
    CHECK (c07 > c06),
    CHECK (c05 = 0 OR c04 IN ('captain', 'first_officer')),
    CHECK ((c12 = 'completed') = (c08 IS NOT NULL))
);

CREATE TABLE tcse (
    c01 INTEGER PRIMARY KEY,
    c02 TEXT NOT NULL UNIQUE,
    c03 INTEGER NOT NULL REFERENCES tu5q(c01),
    c04 INTEGER NOT NULL REFERENCES ts53(c01),
    c05 TEXT NOT NULL CHECK (c05 IN ('line', 'A_check', 'B_check', 'C_check', 'unscheduled')),
    c06 INTEGER CHECK (c06 IS NULL OR c06 BETWEEN 5 AND 80),
