    CHECK (c09 IS NULL OR c09 > c08),
    CHECK ((c16 = 'in_progress') = (c09 IS NULL)),
    CHECK ((c16 = 'completed') = (c10 IS NOT NULL AND c11 IS NOT NULL AND c12 IS NOT NULL)),
    CHECK ((c05 = 'unscheduled') = (c06 IS NOT NULL)),
